raw_distance = "2.5"
try:
    distance_km = float(raw_distance)
    if distance_km < 0:
        raise ValueError("Distance cannot be negative")
    distance_m = distance_km * 1000
    print(f"{distance_km:g} km = {distance_m:g} m")
except ValueError:
    print("Enter a non-negative number of kilometres")

tickets = [
    {"id": "T1", "severity": "critical", "age_hours": 2},
    {"id": "T2", "severity": "normal", "age_hours": 24},
    {"id": "T3", "severity": "normal", "age_hours": 3},
]
for ticket in tickets:
    if ticket["severity"] == "critical":
        priority = "urgent"
    elif ticket["age_hours"] >= 24:
        priority = "review"
    else:
        priority = "standard"
    print(ticket["id"], priority)

contacts = {
    "C001": {"name": "Ali", "city": "Lahore"},
    "C002": {"name": "Ali", "city": "Karachi"},
}
for contact_id, contact in contacts.items():
    print(contact_id, contact["name"], contact["city"])

match = contacts.get("C003")
print("Found" if match is not None else "Contact not found")

import json

contacts = {"C001": {"name": "Ali", "city": "Lahore"}}
saved_text = json.dumps(contacts)
loaded = json.loads(saved_text)
if not isinstance(loaded, dict):
    raise ValueError("Expected a contact directory")
assert loaded == contacts
print("Round trip preserved 1 contact")

